let batchSelection=null;function batchEntries(){return getSavedSkills().map(url=>skillItems.find(x=>x.url===url)).filter(Boolean)}function buildBatchText(){const all=batchEntries(),chosen=all.filter(x=>batchSelection?.has(x.url)),mode=document.querySelector('#skill-copy-mode').value;document.querySelector('#skill-selected-count').textContent=`已选 ${chosen.length} / ${all.length}`;document.querySelector('#copy-skill-bundle').disabled=!chosen.length;let lines=[];if(mode==='commands'){lines=['# 请逐条审阅后运行，安装目录和依赖以目标 Agent 及上游文档为准。'];chosen.forEach(x=>{lines.push('', '# '+x.name, x.command||'# 无已核对的安装命令，请查看：'+x.url)});}else{lines=['请帮我评估并安装以下 Skill。先确认当前 AI 工具、项目路径、安装范围和已安装项；审阅来源、兼容性、许可及依赖后，再给出执行方案。不要一次性安装同一仓库的所有技能。',''];chosen.forEach((x,i)=>lines.push(`${i+1}. ${x.name}`,'用途：'+x.desc,'来源：'+x.url,'工具：'+(x.tools||skillMeta[x.mark]?.tools||'兼容性见来源'),'安装参考：'+(x.command||'请按上游项目说明选择对应工具的安装方式'),''));lines.push('安装后请报告安装位置、缺失依赖、跳过项，并用一个简单任务验证能否被识别。')}document.querySelector('#skill-bundle-text').value=chosen.length?lines.join('\n'):'';document.querySelector('#copy-skill-bundle').textContent='复制给 Agent'}
renderSkillPlan=function(){let entries=batchEntries();if(batchSelection===null)batchSelection=new Set(entries.map(x=>x.url));else{batchSelection=new Set([...batchSelection].filter(url=>entries.some(x=>x.url===url)))}document.querySelector('#skill-plan-count').textContent=entries.length;const list=document.querySelector('#skill-plan-list');list.innerHTML=entries.length?entries.map(x=>`<div class="skill-plan-row"><label class="skill-batch-choice"><input type="checkbox" data-batch-id="${skillItems.indexOf(x)}" ${batchSelection.has(x.url)?'checked':''}><span><strong>${escDash(x.name)}</strong><small>${escDash(x.source)} · ${x.command?'有安装命令':'需查阅安装说明'}</small></span></label><button data-remove-batch="${skillItems.indexOf(x)}">移除</button></div>`).join(''):'<div class="skill-plan-empty">还没有添加 Skill。<a href="#skills">去发现技能 →</a></div>';list.querySelectorAll('[data-batch-id]').forEach(b=>b.onchange=()=>{let url=skillItems[Number(b.dataset.batchId)].url;b.checked?batchSelection.add(url):batchSelection.delete(url);buildBatchText()});list.querySelectorAll('[data-remove-batch]').forEach(b=>b.onclick=()=>toggleSkill(skillItems[Number(b.dataset.removeBatch)].url));buildBatchText()};
const priorToggleSkill=toggleSkill;toggleSkill=function(url){if(!getSavedSkills().includes(url)){if(batchSelection===null)batchSelection=new Set(getSavedSkills());batchSelection.add(url)}priorToggleSkill(url)};document.querySelector('#skill-select-all').onclick=()=>{batchSelection=new Set(batchEntries().map(x=>x.url));renderSkillPlan()};document.querySelector('#skill-select-none').onclick=()=>{batchSelection=new Set();renderSkillPlan()};document.querySelector('#skill-copy-mode').onchange=buildBatchText;renderSkillPlan();
